#include <iostream>
#include <iomanip>
#include <sstream>
#include <vector>
#include <cstring>
#include <type_traits>

// Trivially copyable record struct
struct ClientData {
    int accountNumber{0};
    char lastName[15]{""};
    char firstName[10]{""};
    double balance{0.0};
};
static_assert(std::is_trivially_copyable_v<ClientData>, "ClientData must be trivially copyable");

// Generic output function accepting any std::ostream reference
void outputLine(std::ostream& out, const ClientData& record) {
    out << std::left << std::setw(10) << record.accountNumber
        << std::setw(16) << record.lastName
        << std::setw(11) << record.firstName
        << std::setw(10) << std::setprecision(2) << std::right << std::fixed
        << std::showpoint << record.balance << "\n";
}

int main() {
    // Simulate random-access binary storage (10 slots)
    std::vector<ClientData> storage(10);

    // Populate sparse records in non-sequential order
    storage[8 - 1] = ClientData{8, "Smith", "Dave", 258.34};
    storage[3 - 1] = ClientData{3, "Dunn", "Stacey", 314.33};
    storage[5 - 1] = ClientData{5, "Barker", "Doug", 0.00};

    // Serialize sparse storage into a binary stringstream
    std::stringstream fileStream(std::ios::in | std::ios::out | std::ios::binary);
    for (const auto& slot : storage) {
        fileStream.write(reinterpret_cast<const char*>(&slot), sizeof(ClientData));
    }

    // Reset read pointer to the beginning
    fileStream.seekg(0, std::ios::beg);

    // Print headers
    std::cout << std::left << std::setw(10) << "Account"
              << std::setw(16) << "Last Name"
              << std::setw(11) << "First Name"
              << std::right << std::setw(10) << "Balance" << "\n";

    ClientData client;
    // Read sequentially from the binary stream
    while (fileStream.read(reinterpret_cast<char*>(&client), sizeof(ClientData))) {
        if (client.accountNumber != 0) {
            outputLine(std::cout, client);
        }
    }

    return 0;
}

#include <iostream>
#include <iomanip>
#include <sstream>
#include <vector>
#include <string>
#include <type_traits>

struct ClientData {
    int accountNumber{0};
    char lastName[15]{""};
    char firstName[10]{""};
    double balance{0.0};
};
static_assert(std::is_trivially_copyable_v<ClientData>, "Must be trivially copyable");

enum class Choice : int {
    PRINT = 1,
    UPDATE,
    NEW_REC,
    DELETE_REC,
    END
};

void outputLine(std::ostream& out, const ClientData& record) {
    out << std::left << std::setw(10) << record.accountNumber
        << std::setw(16) << record.lastName
        << std::setw(11) << record.firstName
        << std::setw(10) << std::setprecision(2) << std::right << std::fixed
        << std::showpoint << record.balance << "\n";
}

void updateRecord(std::iostream& file, int account, double transaction) {
    file.seekg((account - 1) * sizeof(ClientData));
    ClientData client;
    file.read(reinterpret_cast<char*>(&client), sizeof(ClientData));

    if (client.accountNumber != 0) {
        client.balance += transaction;
        file.seekp((account - 1) * sizeof(ClientData));
        file.write(reinterpret_cast<const char*>(&client), sizeof(ClientData));
        std::cout << "Updated Account #" << account << " new balance: " 
                  << std::fixed << std::setprecision(2) << client.balance << "\n";
    } else {
        std::cout << "Account #" << account << " does not exist.\n";
    }
}

void printRecords(std::iostream& file) {
    file.clear(); // Reset any EOF/fail flags before seeking
    file.seekg(0);
    std::cout << "\n--- Active Accounts ---\n";
    ClientData client;
    while (file.read(reinterpret_cast<char*>(&client), sizeof(ClientData))) {
        if (client.accountNumber != 0) {
            outputLine(std::cout, client);
        }
    }
    file.clear();
}

int main() {
    // Initialize in-memory stream representing duplex binary storage of 5 accounts
    std::stringstream bankFile(std::ios::in | std::ios::out | std::ios::binary);
    ClientData blankRecord;
    for (int i = 0; i < 5; ++i) {
        bankFile.write(reinterpret_cast<const char*>(&blankRecord), sizeof(ClientData));
    }

    // Populate initial account #2
    ClientData acc2{2, "Doe", "Jane", 500.00};
    bankFile.seekp((2 - 1) * sizeof(ClientData));
    bankFile.write(reinterpret_cast<const char*>(&acc2), sizeof(ClientData));

    // Simulate Transaction: Print, Update (+150.75), Print again
    printRecords(bankFile);

    std::cout << "\nExecuting UPDATE on account 2 (+150.75)...\n";
    updateRecord(bankFile, 2, 150.75);

    printRecords(bankFile);

    return 0;
}
